#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-08

# tests/schemas/test-alpha-channel.sh
#
# Pins the two-entry release channel in .claude-plugin/marketplace.json.
#
# WHY THIS EXISTS
# ---------------
# Before this layout, `ork` used `source: "./plugins/ork"`, a relative path that
# resolves against whatever ref the marketplace is checked out at, i.e. main.
# release-please stamps the version into that same file on every release. So
# merging 10.0.0-alpha to main would have moved EVERY marketplace user onto the
# alpha, and the GitHub "Pre-release" badge would not have stopped it, because
# installation never reads GitHub Releases.
#
# The fix is CC's own mechanism: a plugin `source` may be an object carrying a
# `ref`. `ork` pins the last stable tag; `ork-alpha` tracks main. Opting in is
# an install, not a config edit.
#
# WHAT MAKES THIS FRAGILE, AND WHY THE TEST IS INDEX-AWARE
# --------------------------------------------------------
# release-please addresses the entry to stamp by ARRAY INDEX
# (`$.plugins[1].version`). Reordering the two entries silently redirects the
# stamp onto the pinned stable channel, whose version would then disagree with
# the tag it is pinned to. CC validates that agreement at load, so the failure
# would surface as a broken install for every stable user rather than a red CI
# job. Nothing else in the repo ties that index to the entry it means.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"
MARKETPLACE="$ROOT_DIR/.claude-plugin/marketplace.json"
RP_CONFIG="$ROOT_DIR/.release-please-config.json"
BUMP_SCRIPT="$ROOT_DIR/scripts/bump-stable-pin.sh"
RELEASE_WF="$ROOT_DIR/.github/workflows/release.yml"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; NC=$'\033[0m'
PASS=0; FAIL=0
ok()  { echo "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
bad() { echo "  ${RED}✗${NC} $1"; FAIL=$((FAIL + 1)); }

echo "=========================================="
echo "  Release channel invariants"
echo "=========================================="
echo ""

# ---------------------------------------------------------------------------
# 1. Both channels exist, and each is what its name claims.
# ---------------------------------------------------------------------------
echo "▶ Channel entries"
echo "──────────────────────────────────────"

stable_idx=$(jq -r '[.plugins[].name] | index("ork") // "none"' "$MARKETPLACE")
alpha_idx=$(jq -r '[.plugins[].name] | index("ork-alpha") // "none"' "$MARKETPLACE")

if [[ "$stable_idx" == "none" ]]; then
    bad "no 'ork' entry — stable channel is missing"
else
    ok "stable channel 'ork' at index $stable_idx"
fi
if [[ "$alpha_idx" == "none" ]]; then
    bad "no 'ork-alpha' entry — prerelease channel is missing"
else
    ok "prerelease channel 'ork-alpha' at index $alpha_idx"
fi

echo ""

# ---------------------------------------------------------------------------
# 2. The stable channel is PINNED. This is the whole point.
# ---------------------------------------------------------------------------
echo "▶ Stable channel is pinned, not floating"
echo "──────────────────────────────────────"

if [[ "$stable_idx" != "none" ]]; then
    # Indexes are passed with --argjson, never interpolated into the program
    # text. These values come from jq itself so they are integers today, but
    # the security gate bans the interpolation shape wholesale, and it is right
    # to: data in the program string is how injection starts.
    stable_ref=$(jq -r --argjson i "$stable_idx" '.plugins[$i].source.ref // ""' "$MARKETPLACE")
    stable_ver=$(jq -r --argjson i "$stable_idx" '.plugins[$i].version // ""' "$MARKETPLACE")

    if [[ -z "$stable_ref" ]]; then
        bad "'ork' has no source.ref — it would float to whatever main carries"
    elif [[ "$stable_ref" == "main" || "$stable_ref" == "HEAD" ]]; then
        bad "'ork' is pinned to '$stable_ref', which is not a pin at all"
    else
        ok "'ork' pinned to ref '$stable_ref'"
    fi

    # CC validates that plugin.json and the enclosing marketplace entry agree on
    # the version. Since the entry is pinned to a tag, the declared version must
    # be the version that tag carries, or installs break at load.
    if [[ "$stable_ref" == "v$stable_ver" ]]; then
        ok "'ork' version $stable_ver agrees with its pin $stable_ref"
    else
        bad "'ork' version '$stable_ver' does not match its pin '$stable_ref' (expected ref v$stable_ver)"
    fi
fi

echo ""

# ---------------------------------------------------------------------------
# 3. release-please stamps the ALPHA entry, never the pinned one.
# ---------------------------------------------------------------------------
echo "▶ release-please stamps the prerelease entry"
echo "──────────────────────────────────────"

stamped=$(jq -r '
  .packages["."]["extra-files"][]
  | select(type == "object" and (.path | test("marketplace")) and (.jsonpath | test("plugins")))
  | .jsonpath' "$RP_CONFIG")

if [[ -z "$stamped" ]]; then
    bad "release-please stamps no plugin entry at all"
else
    want="\$.plugins[${alpha_idx}].version"
    if [[ "$stamped" == "$want" ]]; then
        ok "stamps $stamped, which is ork-alpha"
    else
        bad "stamps $stamped but ork-alpha is at index $alpha_idx (want $want)"
        echo "      Reordering the plugins array silently redirects the version"
        echo "      stamp onto the pinned stable channel. Fix the jsonpath."
    fi
fi

echo ""

# ---------------------------------------------------------------------------
# 4. Both channels ship the same plugin directory.
# ---------------------------------------------------------------------------
echo "▶ Both channels point at the same plugin"
echo "──────────────────────────────────────"

if [[ "$stable_idx" != "none" && "$alpha_idx" != "none" ]]; then
    sp=$(jq -r --argjson i "$stable_idx" '.plugins[$i].source.path // ""' "$MARKETPLACE")
    ap=$(jq -r --argjson i "$alpha_idx" '.plugins[$i].source.path // ""' "$MARKETPLACE")
    if [[ -n "$sp" && "$sp" == "$ap" ]]; then
        ok "both resolve path '$sp'"
    else
        bad "channels disagree on path: stable='$sp' alpha='$ap'"
    fi

    su=$(jq -r --argjson i "$stable_idx" '.plugins[$i].source.url // ""' "$MARKETPLACE")
    au=$(jq -r --argjson i "$alpha_idx" '.plugins[$i].source.url // ""' "$MARKETPLACE")
    if [[ -n "$su" && "$su" == "$au" ]]; then
        ok "both resolve the same repository"
    else
        bad "channels disagree on url: stable='$su' alpha='$au'"
    fi

    aref=$(jq -r --argjson i "$alpha_idx" '.plugins[$i].source.ref // ""' "$MARKETPLACE")
    if [[ "$aref" == "main" ]]; then
        ok "'ork-alpha' tracks main"
    else
        bad "'ork-alpha' ref is '$aref', expected 'main'"
    fi
fi

echo ""

# ---------------------------------------------------------------------------
# 5. Something PERFORMS the bump. A guard is not a writer.
# ---------------------------------------------------------------------------
# Section 2 fails when the pin and the version disagree, which catches a
# half-bump AFTER it has been committed. It says nothing about whether anything
# ever moves them, and until #3350 nothing did: on a GA release the pin sat at
# the previous tag until a human noticed. The assertions below execute the
# writer rather than describing it, so they go red if it stops working — not
# only if someone hand-edits the file into disagreement.
echo "▶ The stable pin has an automated writer"
echo "──────────────────────────────────────"

if [[ ! -x "$BUMP_SCRIPT" ]]; then
    bad "scripts/bump-stable-pin.sh is missing or not executable — nothing moves the pin"
else
    ok "scripts/bump-stable-pin.sh is present and executable"

    fixture_dir=$(mktemp -d)
    trap 'rm -rf "$fixture_dir"' EXIT
    fixture="$fixture_dir/marketplace.json"

    # The real file, so the writer is exercised against the shape that actually
    # ships rather than a hand-built stub that can drift away from it.
    cp "$MARKETPLACE" "$fixture"

    # --- GA: both fields move, together, on the PINNED entry ---
    rc=0
    "$BUMP_SCRIPT" 99.0.0 "$fixture" >/dev/null 2>&1 || rc=$?
    if [[ "$rc" -ne 0 ]]; then
        bad "GA bump exited $rc (expected 0) — the writer refused a plain GA version"
    else
        new_ref=$(jq -r '[.plugins[] | select(.source.ref != "main")] | .[0].source.ref' "$fixture")
        new_ver=$(jq -r '[.plugins[] | select(.source.ref != "main")] | .[0].version' "$fixture")
        if [[ "$new_ref" == "v99.0.0" && "$new_ver" == "99.0.0" ]]; then
            ok "GA bump moves ref and version together (99.0.0 @ v99.0.0)"
        else
            bad "GA bump left them disagreeing: version='$new_ver' ref='$new_ref'"
        fi

        # The tracking channel is not the pinned one. Writing by array index is
        # what #3340 was; a writer that hits both entries is the same bug with
        # extra steps.
        alpha_ref=$(jq -r '[.plugins[] | select(.name == "ork-alpha")] | .[0].source.ref // ""' "$fixture")
        alpha_ver=$(jq -r '[.plugins[] | select(.name == "ork-alpha")] | .[0].version // ""' "$fixture")
        real_alpha_ver=$(jq -r '[.plugins[] | select(.name == "ork-alpha")] | .[0].version // ""' "$MARKETPLACE")
        if [[ "$alpha_ref" == "main" && "$alpha_ver" == "$real_alpha_ver" ]]; then
            ok "GA bump leaves 'ork-alpha' untouched (still $alpha_ver @ main)"
        else
            bad "GA bump touched the tracking channel: version='$alpha_ver' ref='$alpha_ref'"
        fi
    fi

    # --- Prerelease: refuses, and changes nothing ---
    # This is the assertion the whole two-channel design rests on. A writer that
    # fires on 10.0.0-alpha.7 would drag every stable installer onto the alpha,
    # which is precisely what pinning exists to prevent.
    cp "$MARKETPLACE" "$fixture"
    before=$(shasum -a 256 < "$fixture")
    rc=0
    "$BUMP_SCRIPT" 99.0.0-alpha.1 "$fixture" >/dev/null 2>&1 || rc=$?
    after=$(shasum -a 256 < "$fixture")
    if [[ "$rc" -eq 3 && "$before" == "$after" ]]; then
        ok "prerelease is a no-op (exit 3, file byte-identical)"
    elif [[ "$before" == "$after" ]]; then
        bad "prerelease bump exited $rc, expected 3 (file was left unchanged)"
    else
        bad "prerelease bump REWROTE the pinned entry — stable installs would follow the alpha"
    fi

    # --- Idempotence: re-running a tag's workflow must not re-commit ---
    rc=0
    "$BUMP_SCRIPT" 99.0.0 "$fixture" >/dev/null 2>&1 || rc=$?
    if [[ "$rc" -ne 0 ]]; then
        bad "idempotence setup: first bump exited $rc, expected 0"
    fi
    rc=0
    "$BUMP_SCRIPT" 99.0.0 "$fixture" >/dev/null 2>&1 || rc=$?
    if [[ "$rc" -eq 3 ]]; then
        ok "re-running an already-applied bump is a no-op (exit 3)"
    else
        bad "second bump to the same version exited $rc, expected 3 (would open a duplicate PR)"
    fi

    rm -rf "$fixture_dir"
    trap - EXIT
fi

# A writer nothing calls is dead code that still reads as coverage — the #959
# class. Pin the call site, not just the file.
if [[ -f "$RELEASE_WF" ]] && grep -q 'scripts/bump-stable-pin\.sh' "$RELEASE_WF"; then
    ok "release.yml invokes scripts/bump-stable-pin.sh"
else
    bad "no tag-triggered workflow calls scripts/bump-stable-pin.sh — the writer is never reached"
fi

echo ""
echo "=========================================="
echo "  Results: ${PASS} passed, ${FAIL} failed"
echo "=========================================="

[ "$FAIL" -eq 0 ] || exit 1
